##### Step 3: Design Fallback Strategies

Define what happens when circuit is open for each dependency:

**Fallback Strategy Matrix:**

| Dependency | Fallback Strategy | Data Staleness Acceptable | Implementation |
|-----------|------------------|-------------------------|----------------|
| EDI Gateway | Queue for retry + cached status | 5 minutes | Redis cache + Service Bus queue |
| Payment Gateway | Return "pending" status | 1 hour | Database state tracking |
| Credentialing API | Use cached license data | 24 hours | SQL Server cache table |
| FHIR API | Return limited member data | 1 hour | Local member summary cache |
| State Eligibility | Use last known eligibility | 30 minutes | Redis cache with TTL |

**Fallback Implementation Example:**

```csharp
// Fallback strategy implementation
public class EdiGatewayCircuitBreakerService
{
    private readonly IAsyncPolicy<EdiResponse> _circuitBreakerPolicy;
    private readonly IDistributedCache _cache;
    private readonly IMessageQueue _retryQueue;

    public async Task<EdiResponse> SubmitClaimAsync(Claim claim)
    {
        var fallbackPolicy = Policy<EdiResponse>
            .Handle<BrokenCircuitException>()
            .FallbackAsync(async (ct) =>
            {
                _logger.LogWarning(
                    "Circuit breaker open for EDI Gateway. Using fallback for claim {ClaimId}",
                    claim.Id);

                // Strategy 1: Check cache for recent submission status
                var cached = await _cache.GetAsync<EdiResponse>(
                    $"edi:claim:{claim.Id}");

                if (cached != null && cached.Timestamp > DateTime.UtcNow.AddMinutes(-5))
                {
                    return cached;
                }

                // Strategy 2: Queue for later retry
                await _retryQueue.EnqueueAsync(new EdiRetryMessage
                {
                    ClaimId = claim.Id,
                    SubmissionData = claim,
                    QueuedAt = DateTime.UtcNow
                });

                // Strategy 3: Return pending status
                return new EdiResponse
                {
                    Status = "Pending",
                    Message = "Submission queued - EDI gateway temporarily unavailable",
                    ClaimId = claim.Id,
                    WillRetryAt = DateTime.UtcNow.AddMinutes(5)
                };
            });

        var combinedPolicy = Policy.WrapAsync(fallbackPolicy, _circuitBreakerPolicy);
        return await combinedPolicy.ExecuteAsync(async () =>
        {
            return await _ediGatewayClient.SubmitAsync(claim);
        });
    }
}
```

