##### Step 4: Implement Circuit Breaker (.NET with Polly)

**A. Install Dependencies:**

```bash
dotnet add package Polly
dotnet add package Polly.Extensions.Http
dotnet add package Microsoft.Extensions.Http.Polly
```

**B. Configure Circuit Breaker Policy:**

```csharp
// Startup.cs or Program.cs
public void ConfigureServices(IServiceCollection services)
{
    // Register circuit breaker for EDI Gateway
    services.AddHttpClient<IEdiGatewayClient, EdiGatewayClient>()
        .AddPolicyHandler(GetCircuitBreakerPolicy())
        .AddPolicyHandler(GetRetryPolicy());

    // Add circuit breaker registry for monitoring
    services.AddSingleton<ICircuitBreakerRegistry, CircuitBreakerRegistry>();
}

private IAsyncPolicy<HttpResponseMessage> GetCircuitBreakerPolicy()
{
    return HttpPolicyExtensions
        .HandleTransientHttpError() // 5xx and 408
        .Or<TimeoutException>()
        .AdvancedCircuitBreakerAsync(
            failureThreshold: 0.5,                    // 50% failure rate
            samplingDuration: TimeSpan.FromSeconds(60),
            minimumThroughput: 10,
            durationOfBreak: TimeSpan.FromSeconds(30),
            onBreak: (outcome, duration) =>
            {
                _logger.LogWarning(
                    "Circuit breaker opened for {Duration}s. Reason: {Reason}",
                    duration.TotalSeconds,
                    outcome.Exception?.Message ?? outcome.Result?.StatusCode.ToString());

                _metrics.RecordCircuitBreakerOpened("edi-gateway", duration);
            },
            onReset: () =>
            {
                _logger.LogInformation("Circuit breaker closed. Service recovered.");
                _metrics.RecordCircuitBreakerClosed("edi-gateway");
            },
            onHalfOpen: () =>
            {
                _logger.LogInformation("Circuit breaker half-open. Testing recovery...");
                _metrics.RecordCircuitBreakerHalfOpen("edi-gateway");
            }
        );
}

private IAsyncPolicy<HttpResponseMessage> GetRetryPolicy()
{
    return HttpPolicyExtensions
        .HandleTransientHttpError()
        .WaitAndRetryAsync(
            retryCount: 3,
            sleepDurationProvider: attempt => TimeSpan.FromSeconds(Math.Pow(2, attempt)),
            onRetry: (outcome, timespan, retryAttempt, context) =>
            {
                _logger.LogWarning(
                    "Retry attempt {RetryAttempt} after {Delay}s",
                    retryAttempt,
                    timespan.TotalSeconds);
            }
        );
}
```

**C. Implement Service Client:**

```csharp
// EdiGatewayClient.cs
public class EdiGatewayClient : IEdiGatewayClient
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<EdiGatewayClient> _logger;
    private readonly ICircuitBreakerRegistry _circuitBreakerRegistry;

    public EdiGatewayClient(
        HttpClient httpClient,
        ILogger<EdiGatewayClient> logger,
        ICircuitBreakerRegistry circuitBreakerRegistry)
    {
        _httpClient = httpClient;
        _logger = logger;
        _circuitBreakerRegistry = circuitBreakerRegistry;

        _httpClient.BaseAddress = new Uri("https://edi-gateway.example.com");
        _httpClient.Timeout = TimeSpan.FromSeconds(10);
    }

    public async Task<EdiResponse> SubmitClaimAsync(Claim claim)
    {
        // Check circuit state before attempting call
        var circuitState = _circuitBreakerRegistry.GetState("edi-gateway");
        if (circuitState == CircuitState.Open)
        {
            _logger.LogWarning("Circuit is open. Request will fail fast.");
            throw new BrokenCircuitException("EDI Gateway circuit breaker is open");
        }

        var request = new HttpRequestMessage(HttpMethod.Post, "/api/v1/claims")
        {
            Content = JsonContent.Create(claim)
        };

        // Circuit breaker and retry policies applied automatically via HTTP client configuration
        var response = await _httpClient.SendAsync(request);
        response.EnsureSuccessStatusCode();

        return await response.Content.ReadFromJsonAsync<EdiResponse>();
    }
}
```

