**C. Implement Service with Circuit Breaker:**

```java
// EdiGatewayService.java
@Service
public class EdiGatewayService {

    private final RestTemplate restTemplate;
    private final CircuitBreakerRegistry circuitBreakerRegistry;
    private final CacheManager cacheManager;
    private final Logger logger = LoggerFactory.getLogger(EdiGatewayService.class);

    @Autowired
    public EdiGatewayService(
            RestTemplate restTemplate,
            CircuitBreakerRegistry circuitBreakerRegistry,
            CacheManager cacheManager) {
        this.restTemplate = restTemplate;
        this.circuitBreakerRegistry = circuitBreakerRegistry;
        this.cacheManager = cacheManager;
    }

    @CircuitBreaker(name = "ediGateway", fallbackMethod = "submitClaimFallback")
    @TimeLimiter(name = "ediGateway")
    public CompletableFuture<EdiResponse> submitClaimAsync(Claim claim) {
        logger.info("Submitting claim {} to EDI Gateway", claim.getId());

        return CompletableFuture.supplyAsync(() -> {
            String url = "https://edi-gateway.example.com/api/v1/claims";

            HttpHeaders headers = new HttpHeaders();
            headers.setContentType(MediaType.APPLICATION_JSON);
            HttpEntity<Claim> request = new HttpEntity<>(claim, headers);

            ResponseEntity<EdiResponse> response = restTemplate.postForEntity(
                url, request, EdiResponse.class);

            // Cache successful response
            cacheManager.getCache("edi-responses")
                .put(claim.getId(), response.getBody());

            return response.getBody();
        });
    }

    // Fallback method - same signature with additional Throwable parameter
    private CompletableFuture<EdiResponse> submitClaimFallback(
            Claim claim, Throwable throwable) {

        logger.warn("Circuit breaker fallback triggered for claim {}. Reason: {}",
            claim.getId(), throwable.getMessage());

        // Try cache first
        Cache.ValueWrapper cached = cacheManager.getCache("edi-responses")
            .get(claim.getId());

        if (cached != null) {
            EdiResponse cachedResponse = (EdiResponse) cached.get();
            if (cachedResponse.getTimestamp()
                    .isAfter(LocalDateTime.now().minusMinutes(5))) {
                logger.info("Returning cached EDI response for claim {}", claim.getId());
                return CompletableFuture.completedFuture(cachedResponse);
            }
        }

        // Queue for retry
        queueForRetry(claim);

        // Return pending response
        EdiResponse pendingResponse = new EdiResponse();
        pendingResponse.setStatus("PENDING");
        pendingResponse.setMessage("EDI Gateway unavailable - claim queued for retry");
        pendingResponse.setClaimId(claim.getId());
        pendingResponse.setWillRetryAt(LocalDateTime.now().plusMinutes(5));

        return CompletableFuture.completedFuture(pendingResponse);
    }

    private void queueForRetry(Claim claim) {
        // Implementation: Add to retry queue (Azure Service Bus, RabbitMQ, etc.)
        logger.info("Claim {} queued for retry", claim.getId());
    }
}
```

**D. Circuit Breaker Event Listener:**

```java
// CircuitBreakerEventListener.java
@Component
public class CircuitBreakerEventListener {

    private final Logger logger = LoggerFactory.getLogger(CircuitBreakerEventListener.class);
    private final MeterRegistry meterRegistry;

    @Autowired
    public CircuitBreakerEventListener(
            CircuitBreakerRegistry registry,
            MeterRegistry meterRegistry) {
        this.meterRegistry = meterRegistry;

        registry.getAllCircuitBreakers().forEach(circuitBreaker -> {
            circuitBreaker.getEventPublisher()
                .onStateTransition(this::onStateTransition)
                .onSuccess(this::onSuccess)
                .onError(this::onError)
                .onCallNotPermitted(this::onCallNotPermitted);
        });
    }

    private void onStateTransition(CircuitBreakerOnStateTransitionEvent event) {
        logger.warn("Circuit breaker {} transitioned from {} to {}",
            event.getCircuitBreakerName(),
            event.getStateTransition().getFromState(),
            event.getStateTransition().getToState());

        // Record metrics
        meterRegistry.counter("circuit.breaker.state.transition",
            "name", event.getCircuitBreakerName(),
            "from", event.getStateTransition().getFromState().toString(),
            "to", event.getStateTransition().getToState().toString()
        ).increment();

        // Send alerts for circuit opening
        if (event.getStateTransition().getToState() == CircuitBreaker.State.OPEN) {
            sendAlert(event.getCircuitBreakerName(), "Circuit breaker opened");
        }
    }

    private void onSuccess(CircuitBreakerOnSuccessEvent event) {
        logger.debug("Circuit breaker {} recorded success. Duration: {}ms",
            event.getCircuitBreakerName(),
            event.getElapsedDuration().toMillis());
    }

    private void onError(CircuitBreakerOnErrorEvent event) {
        logger.error("Circuit breaker {} recorded error: {}",
            event.getCircuitBreakerName(),
            event.getThrowable().getMessage());
    }

    private void onCallNotPermitted(CircuitBreakerOnCallNotPermittedEvent event) {
        logger.warn("Call not permitted - circuit breaker {} is {}",
            event.getCircuitBreakerName(),
            event.getCircuitBreaker().getState());

        meterRegistry.counter("circuit.breaker.calls.rejected",
            "name", event.getCircuitBreakerName()
        ).increment();
    }

    private void sendAlert(String circuitBreakerName, String message) {
        // Implementation: Send alert via PagerDuty, OpsGenie, etc.
    }
}
```

