// CircuitBreakerMetrics.cs
public class CircuitBreakerMetrics
{
    private readonly Counter _openedCounter;
    private readonly Counter _callsRejectedCounter;
    private readonly Gauge _currentStateGauge;
    private readonly Histogram _stateDuration;

    public CircuitBreakerMetrics()
    {
        _openedCounter = Metrics.CreateCounter(
            "circuit_breaker_opened_total",
            "Total number of times circuit breaker opened",
            new CounterConfiguration { LabelNames = new[] { "name", "reason" } });

        _callsRejectedCounter = Metrics.CreateCounter(
            "circuit_breaker_calls_rejected_total",
            "Total number of calls rejected by circuit breaker",
            new CounterConfiguration { LabelNames = new[] { "name" } });

        _currentStateGauge = Metrics.CreateGauge(
            "circuit_breaker_state",
            "Current state of circuit breaker (0=Closed, 1=Open, 2=HalfOpen)",
            new GaugeConfiguration { LabelNames = new[] { "name" } });

        _stateDuration = Metrics.CreateHistogram(
            "circuit_breaker_state_duration_seconds",
            "Duration of circuit breaker states",
            new HistogramConfiguration
            {
                LabelNames = new[] { "name", "state" },
                Buckets = Histogram.ExponentialBuckets(1, 2, 10)
            });
    }

    public void RecordCircuitBreakerOpened(string name, TimeSpan duration)
    {
        _openedCounter.WithLabels(name, "threshold_exceeded").Inc();
        _currentStateGauge.WithLabels(name).Set(1); // Open = 1
    }

    public void RecordCircuitBreakerClosed(string name)
    {
        _currentStateGauge.WithLabels(name).Set(0); // Closed = 0
    }

    public void RecordCircuitBreakerHalfOpen(string name)
    {
        _currentStateGauge.WithLabels(name).Set(2); // HalfOpen = 2
    }

    public void RecordCallRejected(string name)
    {
        _callsRejectedCounter.WithLabels(name).Inc();
    }
}
```

