// CircuitBreakerTests.cs
[TestClass]
public class CircuitBreakerTests
{
    [TestMethod]
    public async Task CircuitBreaker_OpensAfterThresholdExceeded()
    {
        // Arrange
        var mockClient = new Mock<HttpClient>();
        mockClient.Setup(x => x.SendAsync(It.IsAny<HttpRequestMessage>()))
            .ThrowsAsync(new HttpRequestException("Service unavailable"));

        var circuitBreaker = CreateTestCircuitBreaker(
            failureThreshold: 0.5,
            minimumThroughput: 5);

        // Act - Generate failures to exceed threshold
        for (int i = 0; i < 10; i++)
        {
            try
            {
                await circuitBreaker.ExecuteAsync(async () =>
                    await mockClient.Object.SendAsync(new HttpRequestMessage()));
            }
            catch { }
        }

        // Assert
        var state = circuitBreaker.GetState();
        Assert.AreEqual(CircuitState.Open, state);
    }

    [TestMethod]
    public async Task CircuitBreaker_TransitionsToHalfOpenAfterTimeout()
    {
        // Arrange
        var circuitBreaker = CreateTestCircuitBreaker(
            durationOfBreak: TimeSpan.FromSeconds(1));

        // Act - Open the circuit
        await OpenCircuit(circuitBreaker);
        Assert.AreEqual(CircuitState.Open, circuitBreaker.GetState());

        // Wait for timeout
        await Task.Delay(TimeSpan.FromSeconds(1.5));

        // Assert - Circuit should be half-open
        var state = circuitBreaker.GetState();
        Assert.AreEqual(CircuitState.HalfOpen, state);
    }
}
