// EdiGatewayCircuitBreakerConfiguration.cs
public class EdiGatewayCircuitBreakerConfiguration
{
    public IAsyncPolicy<EdiResponse> CreatePolicy()
    {
        // Retry policy: 3 attempts with exponential backoff
        var retryPolicy = Policy<EdiResponse>
            .Handle<HttpRequestException>()
            .Or<TaskCanceledException>()
            .WaitAndRetryAsync(
                retryCount: 3,
                sleepDurationProvider: attempt => TimeSpan.FromSeconds(Math.Pow(2, attempt)),
                onRetry: (outcome, timespan, retryAttempt, context) =>
                {
                    _logger.LogWarning(
                        "EDI submission retry {RetryAttempt} after {Delay}s. Reason: {Reason}",
                        retryAttempt,
                        timespan.TotalSeconds,
                        outcome.Exception?.Message ?? "Unknown");
                });

        // Circuit breaker: Open after 50% failure rate in 60-second window
        var circuitBreakerPolicy = Policy<EdiResponse>
            .Handle<HttpRequestException>()
            .Or<TaskCanceledException>()
            .AdvancedCircuitBreakerAsync(
                failureThreshold: 0.5,                          // 50% failure rate
                samplingDuration: TimeSpan.FromSeconds(60),     // 60-second evaluation window
                minimumThroughput: 10,                          // At least 10 requests
                durationOfBreak: TimeSpan.FromSeconds(30),      // Open for 30 seconds
                onBreak: (outcome, duration, context) =>
                {
                    _logger.LogError(
                        "EDI Gateway circuit breaker OPENED. Duration: {Duration}s. Will test recovery after timeout.",
                        duration.TotalSeconds);

                    _metrics.RecordCircuitBreakerOpened("edi-gateway", duration);
                    _alertService.SendAlert(AlertLevel.ERROR,
                        "EDI Gateway circuit breaker opened - claims in fallback mode");
                },
                onReset: (context) =>
                {
                    _logger.LogInformation("EDI Gateway circuit breaker CLOSED. Service recovered.");
                    _metrics.RecordCircuitBreakerClosed("edi-gateway");
                    _alertService.SendAlert(AlertLevel.INFO,
                        "EDI Gateway circuit breaker closed - normal operation resumed");
                },
                onHalfOpen: () =>
                {
                    _logger.LogInformation("EDI Gateway circuit breaker HALF-OPEN. Testing recovery...");
                    _metrics.RecordCircuitBreakerHalfOpen("edi-gateway");
                });

        // Timeout policy: 10-second timeout per request
        var timeoutPolicy = Policy.TimeoutAsync<EdiResponse>(
            TimeSpan.FromSeconds(10),
            onTimeoutAsync: (context, timespan, abandonedTask) =>
            {
                _logger.LogWarning("EDI submission timed out after {Timeout}s", timespan.TotalSeconds);
                return Task.CompletedTask;
            });

        // Combine policies: Timeout → Retry → Circuit Breaker
        return Policy.WrapAsync(circuitBreakerPolicy, retryPolicy, timeoutPolicy);
    }
}
```

**2. Service Implementation with Fallback:**

```csharp
// ClaimsProcessingService.cs
public class ClaimsProcessingService
{
    private readonly IAsyncPolicy<EdiResponse> _ediCircuitBreaker;
    private readonly IDistributedCache _cache;
    private readonly IServiceBusClient _retryQueue;
    private readonly IEdiGatewayClient _ediClient;

    public async Task<ClaimSubmissionResult> SubmitClaimAsync(Claim claim)
    {
        try
        {
            // Execute with circuit breaker protection
            var ediResponse = await _ediCircuitBreaker.ExecuteAsync(async () =>
            {
                return await _ediClient.SubmitClaimAsync(claim);
            });

            // Success path
            await _cache.SetAsync($"edi:claim:{claim.Id}", ediResponse, TimeSpan.FromMinutes(30));

            return new ClaimSubmissionResult
            {
                Status = "Submitted",
                EdiControlNumber = ediResponse.ControlNumber,
                SubmittedAt = DateTime.UtcNow
            };
        }
        catch (BrokenCircuitException ex)
        {
            // Circuit is open - execute fallback
            _logger.LogWarning(
                "EDI circuit breaker open for claim {ClaimId}. Executing fallback strategy.",
                claim.Id);

            return await ExecuteFallbackStrategy(claim);
        }
    }

    private async Task<ClaimSubmissionResult> ExecuteFallbackStrategy(Claim claim)
    {
        // Fallback Strategy 1: Check for recent cached submission
        var cachedResponse = await _cache.GetAsync<EdiResponse>($"edi:claim:{claim.Id}");
        if (cachedResponse != null &&
            cachedResponse.Timestamp > DateTime.UtcNow.AddMinutes(-5))
        {
            _logger.LogInformation(
                "Returning cached EDI response for claim {ClaimId} (age: {Age} minutes)",
                claim.Id,
                (DateTime.UtcNow - cachedResponse.Timestamp).TotalMinutes);

            return new ClaimSubmissionResult
            {
                Status = "Submitted",
                EdiControlNumber = cachedResponse.ControlNumber,
                SubmittedAt = cachedResponse.Timestamp,
                FromCache = true
            };
        }

        // Fallback Strategy 2: Queue for automatic retry
        await _retryQueue.SendAsync(new EdiRetryMessage
        {
            ClaimId = claim.Id,
            ClaimData = claim,
            QueuedAt = DateTime.UtcNow,
            RetryCount = 0,
            MaxRetries = 5,
            NextRetryAt = DateTime.UtcNow.AddMinutes(5)
        });

        _logger.LogInformation(
            "Claim {ClaimId} queued for EDI retry. Will attempt in 5 minutes.",
            claim.Id);

        // Fallback Strategy 3: Return pending status
        return new ClaimSubmissionResult
        {
            Status = "Pending",
            Message = "EDI gateway temporarily unavailable. Claim queued for automatic submission.",
            WillRetryAt = DateTime.UtcNow.AddMinutes(5),
            IsQueued = true
        };
    }
}
