// CircuitBreakerEventHandler.java
@Component
public class CircuitBreakerEventHandler {

    @Autowired
    private AlertService alertService;

    @Autowired
    private MetricsService metricsService;

    @EventListener
    public void handleCircuitOpened(CircuitBreakerOnStateTransitionEvent event) {
        if (event.getStateTransition().getToState() == CircuitBreaker.State.OPEN) {
            logger.error("Circuit breaker {} OPENED. Failure threshold exceeded.",
                event.getCircuitBreakerName());

            // Determine severity based on circuit breaker name
            AlertLevel level = determineAlertLevel(event.getCircuitBreakerName());

            alertService.sendAlert(level,
                String.format("Payment gateway circuit breaker '%s' opened",
                    event.getCircuitBreakerName()),
                Map.of(
                    "circuit", event.getCircuitBreakerName(),
                    "state", "OPEN",
                    "timestamp", LocalDateTime.now().toString()
                ));

            // Record metric
            metricsService.recordCircuitOpened(event.getCircuitBreakerName());
        }
    }

    private AlertLevel determineAlertLevel(String circuitName) {
        if (circuitName.contains("server-error")) {
            return AlertLevel.CRITICAL;  // Server errors are more serious
        } else if (circuitName.contains("transient")) {
            return AlertLevel.WARNING;   // Transient failures less critical
        } else {
            return AlertLevel.ERROR;     // Default
        }
    }
}
